/**
 * Example: Voice Agent Conversational Think
 *
 * Enables Deepgram's Conversational LLM alongside the primary reasoning model.
 * The example updates the conversational settings after they are applied, then
 * queues a dynamic agent message generated by the Conversational LLM.
 */

const { DeepgramClient } = require("../dist/cjs/index.js");
const { createReadStream } = require("fs");

const deepgramClient = new DeepgramClient({
    apiKey: process.env.DEEPGRAM_API_KEY,
});

async function conversationalThink() {
    const connection = await deepgramClient.agent.v1.createConnection();
    let keepAliveInterval: ReturnType<typeof setInterval> | undefined;
    let sentDynamicMessage = false;

    connection.on("message", (data) => {
        if (data.type === "SettingsApplied") {
            // Runtime updates let you tune the Conversational LLM without replacing
            // the primary Think provider or reconnecting the agent.
            connection.sendUpdateThinkConversational({
                type: "UpdateThink_Conversational",
                think_conversational: {
                    provider: {
                        type: "deepgram",
                        version: "v1",
                        agent_backchannel_sensitivity: 0.15,
                        frustration_max_count: 2,
                    },
                },
            });
        } else if (data.type === "ThinkConversationalUpdated" && !sentDynamicMessage) {
            sentDynamicMessage = true;
            connection.sendInjectDynamicAgentMessage({
                type: "InjectAgentMessage",
                is_dynamic: true,
                behavior: "queue",
            });
        } else if (data.type === "FrustrationDetected") {
            console.log(`Frustration detected (${data.count}); escalated: ${data.escalated}`);
        } else if (data.type === "InjectionRefused") {
            console.warn("Dynamic message was refused:", data.message);
        } else if (data.type === "ConversationText") {
            console.log(`${data.role}: ${data.content}`);
        } else if (data instanceof Blob) {
            console.log("Audio received (bytes):", data.size);
        } else {
            console.log("Message:", data);
        }
    });

    connection.on("error", (error) => {
        console.error("Connection error:", error);
    });

    connection.on("close", () => {
        if (keepAliveInterval) {
            clearInterval(keepAliveInterval);
        }
    });

    connection.connect();

    try {
        await connection.waitForOpen();
        connection.sendSettings({
            type: "Settings",
            audio: {
                input: { encoding: "linear16", sample_rate: 24000 },
                output: { encoding: "linear16", sample_rate: 16000, container: "wav" },
            },
            agent: {
                listen: { provider: { type: "deepgram", model: "nova-3" } },
                think: {
                    provider: { type: "open_ai", model: "gpt-4o-mini" },
                    prompt: "You are a concise and helpful AI assistant.",
                },
                think_conversational: {
                    provider: {
                        type: "deepgram",
                        version: "v1",
                        presence_check_max_count: 1,
                        presence_check_interval_ms: 5000,
                    },
                },
                speak: { provider: { type: "deepgram", model: "aura-2-thalia-en" } },
            },
        });

        keepAliveInterval = setInterval(() => {
            if (connection.socket.readyState === 1) {
                connection.sendKeepAlive({ type: "KeepAlive" });
            }
        }, 5000);

        const audioStream = createReadStream("./examples/spacewalk.wav");
        audioStream.on("data", (chunk) => connection.sendMedia(chunk));
        audioStream.on("end", () => console.log("Finished sending audio"));
        audioStream.on("error", (error) => {
            console.error("Audio stream error:", error);
            connection.close();
        });

        setTimeout(() => {
            connection.close();
            process.exit(0);
        }, 60000);
    } catch (error) {
        console.error("Error configuring Conversational Think:", error);
        connection.close();
    }
}

conversationalThink();
